#Requires -Version 7.2
<#
.SYNOPSIS
    Regenerates large-5k.daml, the lexer benchmark input.

.DESCRIPTION
    Repeats a block of ordinary Daml (records, a template with choices, an interface instance,
    a script with do/case/let, comments, doc comments, a pragma, strings and numbers) with
    numbered names until the file passes 5000 lines. The output is deterministic, so the
    committed file only changes when this script does.
#>
[CmdletBinding()]
param(
    [int] $MinimumLines = 5000
)

$ErrorActionPreference = 'Stop'

$header = @'
{-# LANGUAGE ApplicativeDo #-}
-- | Benchmark input for the lexer: generated by generate-large-5k.ps1, do not edit by hand.
module Large where

import DA.List (sortOn, dedup)
import qualified DA.Map as Map
import DA.Optional (fromOptional)
import Daml.Script

'@

# One block, about 75 lines; {n} becomes the block number.
$block = @'
-- | Holding number {n}, with a few fields of every common type.
data Position{n} = Position{n} with
    account : Text
    quantity : Decimal
    limit : Int
    tags : [Text]
  deriving (Eq, Show)

{- A block comment that spans
   several lines {- with a nested one -}
   before the template. -}
template Asset{n}
  with
    issuer : Party
    owner : Party
    amount : Decimal
    label : Text
    observers : [Party]
  where
    signatory issuer
    observer owner :: observers
    ensure amount > 0.0 && label /= ""

    choice Transfer{n} : ContractId Asset{n}
      with
        newOwner : Party
      controller owner
      do
        assertMsg "cannot transfer to self" (newOwner /= owner)
        create this with owner = newOwner

    nonconsuming choice Inspect{n} : (Text, Decimal)
      controller owner
      do
        pure (label, amount * 1.5e2)

    choice Split{n} : (ContractId Asset{n}, ContractId Asset{n})
      with
        splitAmount : Decimal
      controller owner
      do
        let rest = amount - splitAmount
        first <- create this with amount = splitAmount
        second <- create this with amount = rest
        return (first, second)

-- | Summarises a list of positions; uses `div` and a qualified map.
summarise{n} : [Position{n}] -> Map.Map Text Int
summarise{n} positions =
  let sizes = map (\p -> (p.account, p.limit `div` 2)) positions
  in Map.fromList (sortOn fst (dedup sizes))

classify{n} : Int -> Text
classify{n} x = case x of
  0 -> "zero"
  1 -> "one"
  _ | x < 0x10 -> "small"
    | x < 1_000_000 -> "medium"
    | otherwise -> "large"

test{n} : Script ()
test{n} = script do
  alice <- allocateParty "Alice{n}"
  bob <- allocateParty "Bob{n}"
  cid <- submit alice do
    createCmd Asset{n} with
      issuer = alice; owner = alice; amount = 100.0; label = "asset {n}"; observers = [bob]
  cid' <- submit alice do exerciseCmd cid Transfer{n} with newOwner = bob
  (label, value) <- submit bob do exerciseCmd cid' Inspect{n}
  debug ("got " <> label <> " worth " <> show value) -- ^ trailing note
  pure ()

'@

$lines = [System.Collections.Generic.List[string]]::new()
$lines.AddRange([string[]]($header -split "`r?`n"))
$n = 1
while ($lines.Count -lt $MinimumLines) {
    $lines.AddRange([string[]](($block -replace '\{n\}', $n) -split "`r?`n"))
    $n++
}

$target = Join-Path $PSScriptRoot 'large-5k.daml'
# LF endings on every machine, so the benchmark measures the same text everywhere.
[System.IO.File]::WriteAllText($target, ($lines -join "`n") + "`n", [System.Text.UTF8Encoding]::new($false))
Write-Host "Wrote $($lines.Count) lines ($($n - 1) blocks) to $target"
